import fs from 'node:fs';import path from 'node:path';import {createHash}from'node:crypto';import {digest}from'../live-paper/model.mjs';import {amount,TICK}from'../paper/fixed.mjs';import{atomicJson}from'../execution/ledger.mjs';
const rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup/paper-runtime'),read=f=>JSON.parse(fs.readFileSync(f)),need=(x,c)=>{if(!x)throw Error(c);};
const active=read(path.join(rt,'bulk-dip-active.json')),dir=path.join(rt,'bulk-dip-cohorts',active.cohort),bank=read(path.join(dir,'bank.json')),stats=read(path.join(dir,'stats.json'));
need(digest(bank)===active.bankHash&&stats.bankHash===active.bankHash&&stats.failed===false,'BANK_OR_REPORT');
for(const [file,sha]of Object.entries(bank.codeIdentity))need(createHash('sha256').update(fs.readFileSync(new URL('../live-paper/'+file,import.meta.url))).digest('hex')===sha,'FROZEN_CODE');
let sequence=0,previous=digest(bank),checkpoint;const journal=fs.readFileSync(path.join(dir,'journal.jsonl'));need(journal.at(-1)===10,'PARTIAL_JOURNAL');
for(const line of journal.toString().trimEnd().split('\n')){const row=JSON.parse(line),{hash,...body}=row;need(body.sequence===++sequence&&body.previous===previous&&body.bankHash===active.bankHash&&digest(body)===hash,'JOURNAL_CHAIN');previous=hash;if(sequence===stats.journalSequence)checkpoint=row;}
need(checkpoint?.hash===stats.journalHash&&checkpoint.stateHash===stats.stateHash,'REPORT_CHECKPOINT');
const books=fs.readFileSync(path.join(rt,'public-books.jsonl')).toString().trimEnd().split('\n').map(JSON.parse),wallets={};
for(const[latency,w]of Object.entries(stats.wallets)){
 need(w.recentFills.length===2&&w.closedTrades===1&&w.positions.length===0&&w.pending.length===0&&w.fees==='0.000000'&&w.realizedPnl==='-0.015000','ROUNDTRIP_REPORT');
 const sources=w.recentFills.map(fill=>{const row=books.find(x=>x.kind==='book'&&x.payload.book.versionKey===fill.sourceVersion&&x.payload.book.receivedAt===fill.at);need(row,'FILL_SOURCE');const b=row.payload.book,level=fill.action==='buy'?b.asks[0]:b.bids[0],modeled=amount(level.price)+(fill.action==='buy'?TICK:-TICK);need(modeled===amount(fill.price)&&fill.quantity===1&&Math.floor(level.quantity/100)>=fill.quantity&&fill.fee==='0.000000'&&fill.slippageTicks===1&&fill.depthFractionBps===100,'FILL_MODEL');return {action:fill.action,sequence:row.sequence,hash:row.hash,versionKey:b.versionKey,requestStartedAt:b.requestStartedAt,receivedAt:b.receivedAt,availableAt:row.at,level};});
 need(Date.parse(sources[0].requestStartedAt)>=Date.parse(stats.signals[0].actualAvailableAt)+Number(latency)&&Date.parse(sources[1].requestStartedAt)>Date.parse(sources[0].receivedAt),'POST_ADMISSION');
 wallets[latency]={closedTrades:w.closedTrades,realizedPnl:w.realizedPnl,fees:w.fees,fills:w.recentFills,sources};
}
const result={at:new Date().toISOString(),statsAt:stats.updatedAt,mode:'first_frozen_bulk_prospective_paper_roundtrip',bankHash:active.bankHash,cutoff:bank.cutoff,journalSequence:stats.journalSequence,journalHash:stats.journalHash,journalChainVerified:true,frozenCodeVerified:true,wallets,independentOpportunities:1,networkRequests:0,competitionOrders:0,profitabilityEstablished:false,limitations:['Two latency wallets simulate one correlated opportunity.','Counterfactual next-snapshot taker fills with one-percent depth, one adverse tick per side and zero fees; no contest orders.']};
atomicJson('data/bulk-dip-first-roundtrip-20261003-v2.json',result);console.log(JSON.stringify({at:result.at,bankHash:active.bankHash,journalChainVerified:true,independentOpportunities:1,walletPnl:'-0.015000'}));
